@import "tailwindcss";

:root {
  --background: #ffffff;
  --foreground: #24292f;

  /* GitHub Theme Colors */
  --github-blue: #0969da;
  --github-gray-light: #f6f8fa;
  --github-border: #d0d7de;
  --github-green: #2da44e;
  --github-green-hover: #2c974b;
  --github-gray-text: #57606a;
  --github-gray-dark: #24292f;
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);

  --color-gh-blue: var(--github-blue);
  --color-gh-gray-bg: var(--github-gray-light);
  --color-gh-border: var(--github-border);
  --color-gh-green: var(--github-green);
  --color-gh-green-hover: var(--github-green-hover);
  --color-gh-text-secondary: var(--github-gray-text);
  --color-gh-text-primary: var(--github-gray-dark);

  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", "Noto Sans", Helvetica, Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji";
  --font-mono: ui-monospace, SFMono-Regular, SF Mono, Menlo, Consolas, Liberation Mono, monospace;
}

body {
  background: var(--background);
  color: var(--foreground);
  font-family: var(--font-sans);
}

